function UIBattleEndDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(
            util.cs_generator(
                    function()
                            xTry(function()
                                cs_coroutine.yield_return(BattleEndMgr:ClosePopDialog())   -- 关掉战中的弹出页面
                                -- cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.1))  -- 等页面关完
                                xTry(function()
                                    UIBattlingCtrlMgr:GetInstance():DialogShowStateChange(false) -- 隐藏战中界面
                                end)
                                xTry(function()
                                    local battlingDialog = UIBattlingCtrlMgr:GetInstance():GetBattlingDialog()
                                    if battlingDialog then
                                        battlingDialog:RemoveListener()
                                        battlingDialog:StopCo()  -- 防止有未完的协程或者消息再把战中界面打开
                                    end
                                end)
                                if not isNull(UIBattlingCtrlMgr:GetInstance().tableBattlingBattleInfoDialog) then
                                    -- 移走血条，防止sp点特效露出来
                                    UIBattlingCtrlMgr:GetInstance().tableBattlingBattleInfoDialog:HideAllCharactorInfoNode()
                                end
                                self:BoardEvent2OtherModule()   -- 通知迷宫模块战斗已结算（不知道这个是干啥的）
                                self:InitDialogShowElement() -- 初始化结算 UI 元素（加载，并 SetActive false）
                                GameUtils.ShowBlack(0.45)
                                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.45))
                                BattleEndMgr:HideSceneRole() -- 隐藏当前战场人物
                                self:BattleEndRoleShow() -- 加载结算人物和场景 会等待
                                GameUtils.HideBlack(0.3)
                                if self.showExpAndLevel and BattleEndMgr.passType == 1 then
                                    -- 玩家经验和卡牌经验的打脸展示
                                    self:MakeLevelAndTaskData()
                                end
                                KTool.SetActive(self.RT_ProcessingMask, true)   -- 打开一个接受点击的全屏遮罩

                                local MainQuestMapMgr = import('Game.UI.FightReady.UIMainChapter.UIMainChapter.MainQuestMapMgr')
                                if not IsNull(MainQuestMapMgr:GetInstance().delayDestroyChapterGameOver) then
                                    CS.UnityEngine.GameObject.Destroy(MainQuestMapMgr:GetInstance().delayDestroyChapterGameOver)
                                end
                            end)
                    end))
    return coWait
end

function UIBattleEndDialog:OnShow()
