        self:InitPanelBtn()     -- 设置按钮状态
        xTry(function()
            self:PlayRoleVoice() -- 结算人物声音台词
            self:PlayDialogAnimation() -- 播放界面动画（也是一个声音）
        end)
        KTool.SetActive(self.Container.gameObject, true) -- 激活内容容器

        self:Process()
    end)
end

function UIBattleEndDialog:OnFocus(focus)
