function UIBattleEndDialog:OnFinalize()
    xTry(function()
        local blocker = CS.Engine.UI.UIRaycastBlocker.Instance
        blocker:RemoveCondition("BattleEndProcess")
        
        self:StopInputLimitTimer()
        if isNotNull(self.LT_battleEndLevel) then
            KTool.SafeDelete(self.LT_battleEndLevel.controller.gameObject)
        end
        if not isNull(self.step3Co) then
            cs_coroutine.stop(self.step3Co)
            self.step3Co = nil
        end
        if not isNull(self.processCo) then
            cs_coroutine.stop(self.processCo)
            self.processCo = nil
        end
        self:ClearAutoNextQuest()
        KCookie.RemoveAllListener(Constants.UICacheDataKeys.UIQuestAtId)
        if self.typeQuest == Constants.IDType.QuestCoinsCopy or self.typeQuest == Constants.IDType.QuestExpCopy or self.typeQuest == Constants.IDType.QuestUpStarCopy then
            self:UpdateDailyQuestEnergyPoint()
        end
        Events.Broadcast(Constants.EventNames.CloseExpChangeTips)
        local tipGo = GameObject.Find("CommonTipsBoardBuff")
        if not isNull(tipGo) then
            Events.Broadcast("DestoryCommonTipsBord", nil)
        end

        -- 复原导航条的层级
        local nav = CS.UINavigationBarRoot.Instance
        nav.orderTracker.addSortingOrder = self.navBarSortingOrder
        
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end)
end

