--@region 结算流程
function UIBattleEndDialog:Step1()
    -- 结算UI的入场动画
    self:UIAnimationCountDown()
    -- 角色timeline(自动开始)
    self:EndTimelineCountDown()
    
    -- 设置倒计时
    if self.showTimeCountDown then
        local callback = self.controller.Argument.parameters.countDownCallback
        if isNotNull(callback) then
            self:StartInputLimitTimer(Bind(self, self.UpdateTimerText), callback, 3)
        end
    end
end

--- 计算ui动画的时长
function UIBattleEndDialog:GetUIAnimationDuration()
    local duration = 0.5
    local questId = checkNumber(BattleEndMgr.questId)
    -- 爬塔收菜奖励升级的时候有额外的动画
    local vo12 = QuestConfMgr:GetInstance():GetClimbTowerConfigVo(12)
    local questIds = parse_strings(vo12.num)
    for i, qId in ipairs(questIds) do
        qId = checkNumber(qId)
        if questId == qId then
            duration = 1.2
        end
    end
    return duration
end

function UIBattleEndDialog:Step3()
    local autoClose = teamComponent:GetIsOpenContinue() or teamComponent:GetCurContinueState()
    -- 玩家升级
    -- 玩家等级提升的打脸展示
    ---等待打脸展示队列
    ---@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    if playerComponent then
        return playerComponent:ShowRewardsSpecialDialog(nil, autoClose)
    end
    return nil
end

function UIBattleEndDialog:Process()
    self.processCo = cs_coroutine.start(function()
        local blocker = CS.Engine.UI.UIRaycastBlocker.Instance
        -- step 1
        -- print("[结算流程] start step 1")
        self:Step1()
        while not self:IsStep1Complete() do
            cs_coroutine.yield_return(Yielders.EndOfFrame)
        end
        self:StopStep1Co()

        KTool.SetActive(self.RT_ProcessingMask, false)
        -- print("[结算流程] end step 1")

        blocker:AddCondition("BattleEndProcess")
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.5))  -- 等0.5s再开始下一步
        blocker:RemoveCondition("BattleEndProcess")

        -- 翻牌界面
        if isNotNull(self.controller.Argument.parameters.flipCardData) then
            cs_coroutine.yield_return(self:ShowFlipCardStep())
        end
        
        -- 玩家经验和卡牌经验的打脸展示
        if self.showExpAndLevel and BattleEndMgr.passType == 1
        and self.needShowLevelAndTask then
            -- print("[结算流程] start step 2")
            self:InitLevelAndTaskComp()
            while not self:IsExpCompComplete() do
                cs_coroutine.yield_return(Yielders.EndOfFrame)
            end
            -- print("[结算流程] end step 2")
            blocker:AddCondition("BattleEndProcess")
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.5))
            blocker:RemoveCondition("BattleEndProcess")
        end

        -- step 3 玩家等级提升
        self.step3Co = self:Step3()
        if self.step3Co then
            cs_coroutine.yield_return(self.step3Co)
            self.step3Co = nil
        end

        -- 解锁新道具打脸
        cs_coroutine.yield_return(self:DoUnlockGoodsStep())

        -- 连续作战
        if teamComponent:GetIsOpenContinue() or teamComponent:GetCurContinueState() then
            cs_coroutine.yield_return(self:StepContinuousFight())
        end

        -- 添加好友
        if BattleEndMgr.questType == Constants.IDType.QuestAnnihilation
        and checkNumber(self.panelData.response.canAddFriend) == 1 then
            cs_coroutine.yield_return(self:ShowAddFriendTips())
        end

        if BattleEndMgr.questType == Constants.IDType.Fairyland and not self.panelData.isMirror and self.LB_Fairyland then
            cs_coroutine.yield_return(self.LB_Fairyland:ShowFairylandProgressReward())
        end

        -- 自动下一关
        if isNotNull(self.coAutoNextQuest) then
            self.coAutoNextQuest:Start(AutoNextQuestTimeMax)
        end

        self.processCo = nil
    end)
end

function UIBattleEndDialog:IsStep1Complete()
    if self.endTimelineComplete
    and self.step1UIAnimationComplete
    and (isNull(self.LT_RewardList) or isNull(self.LT_RewardList.coShowGoodsFly)) then
        return true
    end
    return false
end

function UIBattleEndDialog:DirectCompleteStep1()
    -- 直接播放完成
    self:DirectCompleteEndTimeline()
    self.step1UIAnimationComplete = true
    -- 停掉协程
    self:StopStep1Co()
end

function UIBattleEndDialog:StopStep1Co()
    if not isNull(self.step1Co) then
        cs_coroutine.stop(self.step1Co)
        self.step1Co = nil
    end
    self:StopEndTimelineCountDown()
end

--- 跳第一阶段
function UIBattleEndDialog:SkipStep1()
    if not self:IsStep1Complete() then
        -- print("[结算流程] skip step 1")
        self:DirectCompleteStep1()
    end
end

--- 结算UI的入场动画
function UIBattleEndDialog:UIAnimationCountDown()
    self:ShowInitShowComp()
    self.step1UIAnimationComplete = false
    self.step1Co = cs_coroutine.start(function()
        local duration = self:GetUIAnimationDuration()
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(duration))
        -- print("[结算流程] 结束 UI动画")
        self.step1UIAnimationComplete = true
        self.step1Co = nil
    end)
end

--- 结算timeline的计时
function UIBattleEndDialog:EndTimelineCountDown()
    self.endTimelineComplete = true     -- 因为有关卡没有结算timeline所以一上来是true的，等后面检测到有timeline了，才置成false
    self.endTimelineCo = cs_coroutine.start(function()
        while isNull(BattleEndMgr.endTimeline) do
            cs_coroutine.yield_return(Yielders.EndOfFrame)
        end
        self.endTimelineComplete = false
        local completeTime = BattleEndMgr.endTimelineLoopStartTime
        local timer = 0
        -- print("[结算流程] 开始 timeline")
        while not self.endTimelineComplete do
            cs_coroutine.yield_return(Yielders.EndOfFrame)
            timer = timer + Time.deltaTime
            if timer > completeTime then
                -- print("[结算流程] 结束 timeline")
                self.endTimelineComplete = true
            end
        end
        self.endTimelineCo = nil
    end)
end

--- 停止结算timeline的计时
function UIBattleEndDialog:StopEndTimelineCountDown()
    self.endTimelineComplete = true
    if not IsNull(self.endTimelineCo) then
        cs_coroutine.stop(self.endTimelineCo)
        self.endTimelineCo = nil
    end
end

--- 直接完成结算timeline
function UIBattleEndDialog:DirectCompleteEndTimeline()
    -- print("[结算流程] 跳过 timeline", BattleEndMgr.endTimeline, BattleEndMgr.endTimelineLoopStartTime, self.endTimelineComplete)
    if isNull(BattleEndMgr.endTimeline) or self.endTimelineComplete then
        return
    end

    local director = KTool.GetComponent(BattleEndMgr.endTimeline, typeof(PlayableDirector))
    director.time = BattleEndMgr.endTimelineLoopStartTime
    self:StopEndTimelineCountDown()
    -- print("[结算流程] 跳过 timeline")
end

--- 宝箱打脸是否完成
function UIBattleEndDialog:IsExpCompComplete()
    if isNull(self.LT_battleEndLevel) then
        -- 怀疑step2会有实例化失败的情况
        return true
    end
    return self.LT_battleEndLevel.state == false
end
