function UIBattleEndDialog:SetCommonData(dialogArg)
    if isNull(BattleEndMgr) then
        BattleEndMgr = import("Game.UI.UIBattling.BattleEnd.BattleEndMgr")
        BattleEndMgr:Init()
    end
    BattleEndMgr.showData = clone(dialogArg) -- 缓存一份数据到 BattleEndMgr
    BattleEndMgr.passType = dialogArg.isPassed -- 过关状态
    local questId = isSet(dialogArg,"questId") and dialogArg.questId or (isSet(dialogArg, "response") and dialogArg.response.questId) -- 关卡 ID
    BattleEndMgr.questId = questId
    if self.panelData.isMirror then
        BattleEndMgr.questType = Constants.IDType.Fairyland
    else
        BattleEndMgr.questType = GoodsUtils.GetIdType(questId, Constants.IDArea.Quests) -- 关卡类型
    end
end

