function UIBattleEndDialog:InitPanelBtn()
    UIEventProxy.Create(self.RT_ProcessingMask.gameObject).onPointerClick = function()
        self:SkipStep1()
    end

    if self.showTimeCountDown then
        -- 显示倒计时，关闭确定按钮
        KTool.SetActive(self.Img_btnClosePanel, false)
        KTool.SetActive(self.RT_CountDown, true)
    else
        -- 显示确定按钮，关闭倒计时
        SetButtonAction(self.Img_btnClosePanel, Bind(self, self.OnCloseBtn))
        KTool.SetActive(self.RT_CountDown, false)
    end
    
    --- 结算统计按钮显示状态
    KTool.SetActive(self.BtnStatistic.gameObject, (not IsNull(self.panelData)) and isSet(self.panelData, "response") and isSet(self.panelData.response, "statistic"))
    --- 设置战斗结算 人物数据统计 界面 入口点击事件
    SetButtonAction(self.BtnStatistic, function()
        self:ClearAutoNextQuest()
        --- 页面查重
        local panelIsActive = false
        local dialogs = UIModule.CurrentScreen.dialogs
        for i, v in pairs(dialogs) do
            if v.Argument.id == PATH_STATISTIC_DIALOG then
                panelIsActive = true
            end
        end
        if not panelIsActive and self.panelData.response then
            UIModule.OpenDialog({ id = PATH_STATISTIC_DIALOG, parameters = { data = self.panelData.response.statistic } })
        end
    end)
    -- 设置经验和任务界面的入口按钮
    if self.showExpAndLevel and BattleEndMgr.passType == 1
    and self.needShowLevelAndTask then
        SetButtonAction(self.BtnLv, function ()
            self:ClearAutoNextQuest()
            self.LT_battleEndLevel:SetActive(true)
            self.LT_battleEndLevel:ReshowLevelPanel(self.playerExpInfo, self.cardExpInfo, self.taskInfo)
        end)
    else
        KTool.SetActive(self.BtnLv.gameObject, false)
    end
end

function UIBattleEndDialog:OnCloseBtn()
    if not IsNull(self.Img_btnClosePanel) then
        self.Img_btnClosePanel.enabled = false
    end
    self:ClearAutoNextQuest()
    -- GameUtils.ShowBlackOverlay()
    if self.panelData.callback then
        self.panelData.callback()
    end
    teamComponent:SetIsOpenContinue(false)  -- 关闭连续战斗
end

