function UIBattleEndDialog:InitCompTitle()
    local goRoot = self:CreateResGameObject(Constants.BattleEndCompResPath.UIBattleEndTitle, self.Container, io.pathInfo(Constants.BattleEndCompResPath.UIBattleEndTitle).basename, true)
    if not IsNull(goRoot) then
        local _LB_TitleRoot = GetLuaBehaviour(goRoot, Constants.BattleEndCompLuaPath.UIBattleEndTitle)
        if not IsNull(_LB_TitleRoot) then
            _LB_TitleRoot:Init()
