---InitCompRewardList
---初始化奖励列表节点
function UIBattleEndDialog:InitCompRewardList()
    if self.typeQuest == Constants.IDType.Fairyland and not self.panelData.isMirror then
        return    
    end

    local passType = BattleEndMgr.passType
    local isShowRole = BattleEndMgr:GetPanelShowType(passType)
    local rewardsData = BattleEndMgr:GetBattleEndRewardsList()
    local questReturnHP = BattleEndMgr:GetReturnPlayerHPValue()
    local showVictoryReward = isShowRole and (not isNull(rewardsData)) and #rewardsData > 0
    local showReturnHP = false
    --(not isShowRole) and (not IsNull(questReturnHP)) and questReturnHP > 0
    if showVictoryReward or showReturnHP or BattleInfo:IsPVP() then
        local goRoot = self:CreateResGameObject(Constants.BattleEndCompResPath.UIBattleEndMissionRewardsList, self.Container)
        if not IsNull(goRoot) then
            local _LB_RewardListRoot = GetLuaBehaviour(goRoot, Constants.BattleEndCompLuaPath.UIBattleEndMissionRewardsList)
            if not IsNull(_LB_RewardListRoot) then
                _LB_RewardListRoot:Init()
                local _LT_RewardListRoot = _LB_RewardListRoot.Env
                if showReturnHP then
                    _LT_RewardListRoot:SetReturnPlayerHP()
                end
                if showVictoryReward or BattleInfo:IsPVP() then
                    _LT_RewardListRoot:SetRewardRootInfo()
                    _LT_RewardListRoot:SetExtraReward()
                end
                self.LT_RewardList = _LT_RewardListRoot
            end
        end
        table.insert(self.listGOComp, goRoot)
    end
end

function UIBattleEndDialog:InitFairylandRewards()
    if BattleEndMgr.passType  ~= 1 then
        return
    end

    if self.typeQuest == Constants.IDType.Fairyland and not self.panelData.isMirror then
        local goRoot = self:CreateResGameObject(Constants.BattleEndCompResPath.UIBattleEndFairyland, self.Container)
        if not IsNull(goRoot) then
            local _LB_Fairyland = CfUtils.GetLuaScr(goRoot, Constants.BattleEndCompLuaPath.UIBattleEndFairyland)
            if not IsNull(_LB_Fairyland) then
                _LB_Fairyland:Initialization()
                self.LB_Fairyland = _LB_Fairyland
            end
        end
        table.insert(self.listGOComp, goRoot)
    end
end

function UIBattleEndDialog:ShowPlayerHPReturn()
    xTry(function()
        local passType = BattleEndMgr.passType
        local isShowRole = BattleEndMgr:GetPanelShowType(passType)
        local questId = UIBattlingDataMgr:GetQuestId()
        local questVo = QuestConfMgr:GetInstance():GetQuestVoById(questId)
        if IsNull(questVo) then return end
        if not isSet(questVo, "costItem") then return end
        if not isSet(questVo, "costNumLose") then return end
        local numCost = checkNumber(questVo.costNumLose)
        local idGoodsCost = checkNumber(questVo.costItem)
        if (not isShowRole) and (not IsNull(numCost)) and numCost > 0 then
            local goodsVo = checkTable(GoodsConfMgr:GetInstance():GetGoodsVoById(idGoodsCost))
            local goodsName = checkString(goodsVo.name)
            self.TxtState2.text = localize("消耗_num__name_", {_num_ = numCost, _name_ = goodsName})
            KTool.SetActive(self.TxtState2.gameObject, true)
        end
    end)
end


---InitBattleFailureComp
---初始化关卡失败相关部分
function UIBattleEndDialog:InitBattleFailureComp()
    if BattleInfo.gameMode == Constants.GameMode.PVP then return end
    if BattleInfo.isSimulator then return end
    local questVo = QuestConfMgr:GetInstance():GetQuestVoById(BattleEndMgr.questId)
    if isNotNull(questVo) and isNotNull(questVo.isBossChallengeQuest) and (questVo.isBossChallengeQuest == true) then return end
    local passType = BattleEndMgr.passType
    local questType = BattleEndMgr.questType
    local showData = BattleEndMgr.showData
    local isShowRole = BattleEndMgr:GetPanelShowType(passType, questType, showData.response)
    local isDirectional = questType == Constants.IDType.QuestDirectionalFight
    local showDefeat = (not isShowRole) and (not isDirectional)
    local showCardDJ = BattleEndMgr:GetJump2CultivateCardDJ()
    local isWholeRob  = BattleEndMgr:IsWholeRobTeam()
    -- print("->UIBattleEndDialog:InitJump2OtherEntity:_isWholeRob, _showCardDJ", isWholeRob, showCardDJ)
    if showDefeat and isWholeRob then
        self:SetBattleEndTipsInfo(isWholeRob, nil)
        return
    end
    if showDefeat and showCardDJ then
        local jumpMode = UIBattlingTools.GetUIDialogJumpMode(questType)
        self:InitJump2OtherEntity(jumpMode)
    end
end

