        end
    else
        RoleVoiceMgr:GetInstance():PlayGradeFailedVoiceByCardId(roleData.cardId)
    end
end

---SetOpenTeamDialog
---设置跳转入口
function UIBattleEndDialog:SetRepeatBtn()
    local questType = BattleEndMgr.questType
    local questId = BattleEndMgr.questId
    local questVo = QuestConfMgr:GetInstance():GetQuestVoById(questId)
    local showData = BattleEndMgr.showData

    -- 跳转函数
    local _onJump = function(questId, needTeamFormation)
        if isNotNull(self.coAutoNextQuest) then
            self.coAutoNextQuest:Stop()
            self.coAutoNextQuest = nil
        end
        local fightPreWarMgr = FightPreWarMgr:GetInstance()
        local args = fightPreWarMgr:GetBattleArgs()
        if needTeamFormation == false then
            -- 直接重启战斗
            local curLevelVo = QuestConfMgr:GetInstance():GetQuestVoById(questId)
            local hasNum = GoodsUtils.GetThingNo(curLevelVo.costItem) --体力
            if checkNumber(curLevelVo.costItem) == ActionUtils.GetDailyQuestTicketId() then
                hasNum = ActionUtils.GetDailyQuestCurTicketAddNum()    -- sp门票
            end
            
            local costLevelNum = checkNumber(curLevelVo.costNum)
            -- 计算全局buff加成后需要的消耗道具数量
            costLevelNum = GameUtils.CalculateCostNumWithTalentAddition(curLevelVo, costLevelNum)
            if checkNumber(args.isThreeTripleMode) == 1 then
                costLevelNum = (3 - checkNumber(showData.response.freeTimesRemain)) * costLevelNum
            else
                if checkNumber(showData.response.freeTimesRemain) > 0 then
                    costLevelNum = 0
                end
            end

            if hasNum < costLevelNum then-- + checkNumber(curLevelVo.costNumLose)) then
                if checkNumber(curLevelVo.costItem) == Constants.Currency.HpId then
                    UIModule.OpenDialog({id = Constants.UITypeIds.UIHPDialog, parameters = { overrideSorting = 1050, hideBtnMore = true } })
                else
                    local goodVo = GoodsConfMgr:GetInstance():GetGoodsVoById(checkNumber(curLevelVo.costItem))
                    GameUtils.Toast(localize("_name_不足",{_name_ = goodVo.name}))
                end
                return
            end

            GameUtils.RestartBattle(questId)
        elseif needTeamFormation == true then
            --- ui界面栈添加编队界面
            local fightTeamArgs = fightPreWarMgr:GetFightTeamArgs()
            fightTeamArgs.levelId = questId --更新字段信息
            UIModule.AddUIPage({ id = Constants.UITypeIds.UIFightTeamChoose, parameters = fightTeamArgs })
            GameUtils.OpenLoadingPanel({ id = Constants.UITypeIds.UISceneHome }, nil, Constants.LoadingType.MainHome)
            return
        end
    end
    -- 获取关卡id
    local _GetQuestId = function(questId, btnType)
        if btnType == 1 then
            -- 重复本关的id
            return questId
        elseif btnType == 2 then
            -- 下一关的id
            if isSet(questVo, "nextLevel") and questVo.nextLevel > 0 then
                return checkInt(questVo.nextLevel)
            else
                printError("没找到下一关卡的id", questType, questId)
                return questId
            end
        else
            return questId
        end
    end
    -- 设置按键描述
    local _SetBtnDesc = function(pQuestType, btnType)
        local transTxtBtn = self.NextBtn.transform:Find("Text")
        if not IsNull(transTxtBtn) then
            local txtBtn = transTxtBtn.gameObject:GetComponent(typeof(CS.UnityEngine.UI.Text))
            if not IsNull(txtBtn) then
                if btnType == 1 then
                    txtBtn.text = localize("再次挑战")
                elseif btnType == 2 then
                    txtBtn.text = localize("下一关")
                end
            end
        end
    end
    --- 绑定按钮
    local _FuncJump = function(pQuestType, pQuestId, btnType, needTeamFormation)
        local _levelId = pQuestId
        _levelId = _GetQuestId(pQuestId, btnType)
        _SetBtnDesc(pQuestType, btnType)
        SetButtonAction(self.NextBtn, function()
            _onJump(_levelId, needTeamFormation)
        end)
        if btnType == 2 then
            CfUtils.FillText(self.NextBtnDesc, localize("3秒自动进入下一关"))
            local TimeCoroutine = import('Game.Behaviours.TimeCoroutine')
            ---@type TimeCoroutine
            local timeCo = TimeCoroutine(2)
            timeCo:OnTimerCallback(function(time)
                CfUtils.FillText(self.NextBtnDesc, localize("_num_秒自动进入下一关", {_num_ = AutoNextQuestTimeMax - time}))
            end)
            timeCo:OnTimerEndCallback(function()
                _onJump(_levelId, needTeamFormation)
            end)
            self.coAutoNextQuest = timeCo
        end
    end

    -- 判断是否显示按钮，按钮类型
    local isShowBtn = false
    local btnType = 1
    local needTeamFormation = false
    xTry(function() 
        if BattleEndMgr.passType == 1 then
            -- 胜利时
            local hasKey = (not IsNull(questVo)) and isSet(questVo, "repeatButton") and questVo.repeatButton > 0
            if hasKey then
                if questVo.repeatButton == 1 then
                    -- 显示重复挑战
                    isShowBtn = true
                    btnType = 1
                    needTeamFormation = false
                elseif questVo.repeatButton == 2 then
                    -- 倒计时3s自动进入下一关
                    isShowBtn = true
                    btnType = 2
                    needTeamFormation = false
                end
            end
        else
            -- 失败时
            local hasKey = (not IsNull(questVo)) and isSet(questVo, "replayButton") and questVo.replayButton > 0
            if hasKey then
                if questVo.replayButton == 1 then
                    -- 显示重复挑战
                    isShowBtn = true
                    btnType = 1
                    needTeamFormation = false
                elseif questVo.replayButton == 2 then
                    -- 倒计时3s自动进入下一关
                    isShowBtn = true
                    btnType = 2
                    needTeamFormation = false
                end
            end
        end
    end)

    -- 检查还有没有下一关了
    if isShowBtn and btnType == 2 then
        if questType == Constants.IDType.QuestTower then
            local hasNextQuest = OverseaTowerUtils.HasNextQuest(questId)
            if not hasNextQuest then
                isShowBtn = false
            end
        end
    end

    -- 进入下一关之前，需要先请求解锁的处理
    if isShowBtn and btnType == 2 then
        if questType == Constants.IDType.QuestTower
        and OverseaTowerUtils.GetTowerType(questId) ~= Constants.TowerType.Main then
            local originOnJump = _onJump
            _onJump = function(questId, needTeamFormation)
                OverseaTowerUtils.RequestUnlockNextQuest(questId, function()
                    originOnJump(questId, needTeamFormation)
                end)
            end
        end
    end

    --- 设置按钮显示状态 && 绑定点击事件
    KTool.SetActive(self.NextBtn.gameObject, checkBool(isShowBtn))
    KTool.SetActive(self.NextBtnDesc.gameObject, checkBool(isShowBtn) and (btnType == 2))
    if isShowBtn then
        _FuncJump(questType, questId, btnType, needTeamFormation)
    end
end

