function UIBattleEndDialog:MakeLevelAndTaskData()
    if not isNull(self.panelData.playerOldLv) then
        local playerOldLv = checkNumber(self.panelData.playerOldLv)
        local playerOldExp = 0
        local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        if playerComponent then
            playerOldExp = checkNumber(playerComponent:GetExpBefore())
        end

        -- 玩家经验信息
        self.playerExpInfo = {
            newLv = checkNumber(self.panelData.response.playerLv),
            oldLv = playerOldLv,
            newExp = checkNumber(self.panelData.response.mainExp),
            oldExp = playerOldExp,
        }
        -- print("[结算] 玩家经验信息 ", table.dump(self.playerExpInfo))
    end
    
    if not isNull(self.panelData.cardExpInfo) then
        -- 卡牌经验信息
        self.cardExpInfo = checkTable(self.panelData.cardExpInfo)
        -- print("[结算] 卡牌经验信息 ", table.dump(self.cardExpInfo, nil, 4))
    end
    
    -- 初始数据里的任务信息
    self.taskInfo = {}
    local fightData = FightPreWarMgr:GetInstance():GetFightData()
    if not isNull(fightData) then
        self.taskInfo = checkTable(fightData.questGradeTaskProgress)
    end
    -- print("[结算] 初始任务信息 ", table.dump(self.taskInfo, nil, 3))

    if not isNull(self.panelData.response) then
        -- 再加上结算数据里的任务信息.如果和初始数据里的任务有相同id，那么覆盖初始数据里的任务进度，因为结算时候的任务进度肯定更高
        local tasks = checkTable(self.panelData.response.questGradeTaskProgress)
        for k, v in pairs(tasks) do
            self.taskInfo[k] = v
        end
        -- print("[结算] 结算任务信息 ", table.dump(self.taskInfo, nil, 3))
    end

    local playerLvChanged = isNotNull(self.playerExpInfo) and (self.playerExpInfo.newLv ~= self.playerExpInfo.oldLv) or false
    local playerExpChanged = isNotNull(self.playerExpInfo) and (self.playerExpInfo.newExp ~= self.playerExpInfo.oldExp) or false
    local hasCardExp = table.count(self.cardExpInfo) > 0
    local hasTask = table.count(self.taskInfo) > 0
    self.needShowLevelAndTask = playerLvChanged or playerExpChanged or hasCardExp or hasTask
    -- print("[结算] 经验打脸显示", playerLvChanged, playerExpChanged, hasCardExp, hasTask, self.needShowLevelAndTask)
end

--- 连续作战阶段
function UIBattleEndDialog:StepContinuousFight()
    -- 保存奖励列表
    local rewards = BattleEndMgr:GetBattleEndRewardsList()
    local extraRewards = BattleEndMgr:GetExtraRewardsList()
    teamComponent:AddContinueFightRewards(rewards, extraRewards)

    -- 检查是否满足继续作战的条件
    local state, type, msg = self:GetContinuousFightState()

    -- 如果材料不足，尝试兑换
    if not state
    and type == 4
    and teamComponent:GetIsAutoUseComsume() then
        local enough, costId, costNum = self:IsConvertItemEnough()
        if enough then
            local exchangeResult = {success = false}
            cs_coroutine.yield_return(self:ExchangeConsumeItem(costId, costNum, exchangeResult))
            if exchangeResult.success then
                teamComponent:AddExchangeItemCostNum(costNum)   -- 记录兑换道具消耗数量
                -- 兑换成功
                state = true
            end
        end
    end

    -- 看看是否可以继续
    if state then
        -- 继续
        -- 弹出继续作战的确认倒计时
        cs_coroutine.yield_return(GameUtils.ShowDialogAndYield({ id = Constants.UITypeIds.UIBattleEndContinuousFightConfirmDialog }))
        -- 判断玩家是否打断了连续作战
        if teamComponent:GetCurContinueState() then
            -- 继续作战
            teamComponent:SetIsOpenContinueState(true)
            GameUtils.RestartBattle(BattleEndMgr.questId)
            return
        else
            -- 中止
            state = false
            msg = localize("连续作战完成，请确认奖励内容")
        end
    end
    if not state then
        -- 中止
        cs_coroutine.yield_return(GameUtils.ShowDialogAndYield({ id = Constants.UITypeIds.UIBattleEndContinuousFightSummaryDialog, 
            parameters = { content = msg } }))
        teamComponent:ResetContinueState()
    end
end

--- 获取连续作战状态
function UIBattleEndDialog:GetContinuousFightState()
    local state = false
    local type = -1
    local msg = "null"
    if BattleEndMgr.passType ~= 1 then
        -- 战斗失败
        state = false
        type = 1
        msg = localize("战斗失败，连续作战中止")
    elseif self.panelData.needShowAnnihilationPopup then
        -- 歼灭战开启
        state = false
        type = 2
        msg = localize("巨型傀入侵，连续作战中止")
    elseif not teamComponent:GetCurContinueState()
    or teamComponent:IsReachMaxTimes() then
        -- 作战完成
        state = false
        type = 3
        msg = localize("连续作战完成，请确认奖励内容")
    elseif not self:IsConsumeItemEnough() then
        -- 材料不足
        state = false
        type = 4
        msg = localize("挑战材料不足，连续作战中止")
    elseif GoodsUtils.IsPacketFilled() then
        local isFilled, packetVo = GoodsUtils.IsPacketFilled()
        state = false
        type = 5
        msg = localize("_name_背包已满，请前往清理", {_name_ = packetVo.name})
    else
        state = true
    end
    return state, type, msg
end

--- 检查消耗道具是否足够
function UIBattleEndDialog:IsConsumeItemEnough()
    local questId = BattleEndMgr.questId
    local curLevelVo = QuestConfMgr:GetInstance():GetQuestVoById(questId)
    
    -- 存有的消耗道具数量
    local costNum = GoodsUtils.GetThingNo(curLevelVo.costItem)  -- 体力
    if checkNumber(curLevelVo.costItem) == ActionUtils.GetDailyQuestTicketId() then
        costNum = ActionUtils.GetDailyQuestCurTicketAddNum()    -- 副本门票
    end

    -- 需要的消耗道具数量
    local needNum = (checkNumber(curLevelVo.costNum) + checkNumber(curLevelVo.costNumLose))
    -- 计算全局buff加成后需要的消耗道具数量
    needNum = GameUtils.CalculateCostNumWithTalentAddition(curLevelVo, needNum)
    if curLevelVo then
        if checkNumber(curLevelVo.levelType) == Constants.RegionSecondQuestType.Equip then
            ---装备本
            --@type PlayerComponent
            local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
            local status = checkNumber(playerComponent.playerDojo.consumeCopyActivity.status)
            local times = checkNumber(playerComponent.playerDojo.consumeCopyActivity.residueNum)
            if status == 1 and times > 0  then
                ---@type TableML.TableFile
                local tableFile = settingModule.Get(AutoIds.IdSetting313)
                ---@type TableML.TableFileRow
                local row = tableFile:GetByPrimaryKey(checkNumber(questId), false)
                if row then
                    needNum = checkNumber(row:Get("costNum")) + checkNumber(curLevelVo.costNumLose)
                end
            end
        end
    end
    return costNum >= needNum
end

--- 兑换道具是否足够
function UIBattleEndDialog:IsConvertItemEnough()
    local questId = BattleEndMgr.questId
    local curLevelVo = QuestConfMgr:GetInstance():GetQuestVoById(questId)

    local costId = Constants.Currency.HpExchangeID
    if checkNumber(curLevelVo.costItem) == Constants.Currency.HpId then
        costId = Constants.Currency.HpExchangeID
    elseif checkNumber(curLevelVo.costItem) == ActionUtils.GetDailyQuestTicketId() then
        costId = Constants.Currency.SPTicketExchangeId
    end

    local vo =  CfUtils.GetCfVo(AutoIds.IdSetting302, "ExchangeStrengthVo", costId)
    local curNum = GoodsUtils.GetThingNo(costId)
    local costNum = checkNumber(vo.itemIdCost)
    local enough = curNum >= costNum
    return enough, costId, costNum
end

--- 兑换消耗道具
function UIBattleEndDialog:ExchangeConsumeItem(costId, costNum, exchangeResult)
    local requestSuccess = false
    local t = {goodsId = costId, num = costNum}
    GameUtils.Request(Interfaces.PlayerStrengthHP, {consume = table.serialize(t)}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            requestSuccess = true
            exchangeResult.success = false
            return
        end
        requestSuccess = true
        exchangeResult.success = true
        local jsonData = response.data

        GoodsUtils.DrawRewards({[1] = {goodsId = costId, num = -costNum}})   -- 减少兑换道具

        local curLevelVo = QuestConfMgr:GetInstance():GetQuestVoById(BattleEndMgr.questId)
        if checkNumber(curLevelVo.costItem) == Constants.Currency.HpId then
            -- 加体力
            GoodsUtils.DrawRewards(jsonData.rewards, true)
        elseif checkNumber(curLevelVo.costItem) == ActionUtils.GetDailyQuestTicketId() then
            -- 加门票
            local vo =  CfUtils.GetCfVo(AutoIds.IdSetting302, "ExchangeStrengthVo", costId)
            local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.DailyQuestComponent)
            comp:AddTicketCount(checkNumber(vo.getItemCost) * costNum)
            Events.Broadcast(Constants.EventNames.EveryThingChangeEventName)
        end
        -- print("[连续作战] 自动兑换", costId, -costNum)
    end)
    while not requestSuccess do
        cs_coroutine.yield_return()
    end
end

--- 获取结算奖励中新解锁的道具
function UIBattleEndDialog:GetUnlockGoodsInRewards()
    local unlockGoods = {}
    local rewards = BattleEndMgr:GetBattleEndRewardsList()
    -- rewards = {
    --     [1] = {
    --         ["num"] = 1,
    --         ["goodsId"] = 5510001,
    --     },
    --     [2] = {
    --         ["num"] = 1,
    --         ["goodsId"] = 5400002,
    --     },
    -- }
    for i, v in pairs(rewards) do
        local goodsType = GoodsUtils.GetIdType(v.goodsId)
        if goodsType == Constants.IDType.RestaurantRecipeGoods
        or goodsType == Constants.IDType.GoodsCD then
            table.insert(unlockGoods, v)
        end
    end
    return unlockGoods
end

--- 展示解锁新道具打脸
function UIBattleEndDialog:DoUnlockGoodsStep()
    local unlockGoods = self:GetUnlockGoodsInRewards()
    if table.count(unlockGoods) > 0 then
        for i, v in ipairs(unlockGoods) do
            GameUtils.ShowDialogAndYield({ id = Constants.UITypeIds.CultivateLevelUpSecondConfirmPanel, parameters = {
                levelUpType = Constants.UICultivateLevelUpFinishType.GetRecipe,
                data = v,
                openMainCamera = true,
                autoHide = teamComponent:GetIsOpenContinue() or teamComponent:GetCurContinueState(),
            } })
        end
    end
end

function UIBattleEndDialog:ShowAddFriendTips()
    local wait = true
    local otherId = UIBattlePlayerInfoMgr:GetOtherPlayerId()
    local otherName = UIBattlePlayerInfoMgr:GetOtherPlayerName()
    GameUtils.SecondConfirm(localize("是否要添加_name_为好友", {_name_ = otherName}),function()
        GameUtils.Request(Interfaces.FriendAddFriend, {friendId = otherId}, function(request, response)
            if checkInt(response.errCode) == 0 then
                GameUtils.Toast(localize("好友申请已发送"))
            end
        end)
        wait = false
    end, function()
        wait = false
    end)
    while wait do
        cs_coroutine.yield_return(Yielders.EndOfFrame)
    end
end

--- 翻牌奖励界面
function UIBattleEndDialog:ShowFlipCardStep()
    GameUtils.ShowDialogAndYield({id = Constants.UITypeIds.UIActivityFoodAnnihilationFilpCardDialog, parameters = self.controller.Argument.parameters.flipCardData})
end

--- 倒计时
---@param callBackCD any
---@param callBackFinish any
---@param timeLimit any
function UIBattleEndDialog:StartInputLimitTimer(callBackCD, callBackFinish, timeLimit)
    self.coInputLimitTimer = cs_coroutine.start(function()
        local timer = 0
        while timer < timeLimit do
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1))
            timer = timer + 1
            if callBackCD then
                callBackCD(timeLimit - timer)
            end
        end
        if callBackFinish then
            callBackFinish()
        end
        self.coInputLimitTimer = nil
    end)
end

function UIBattleEndDialog:StopInputLimitTimer()
    if self.coInputLimitTimer then
        cs_coroutine.stop(self.coInputLimitTimer)
        self.coInputLimitTimer = nil
    end
end

function UIBattleEndDialog:UpdateTimerText(remainTime)
    self.Txt_CountDown.text = tostring(remainTime)
end

return UIBattleEndDialog
